from pathlib import Path
import json
names=['Sapphire Vault','Knowledge Pavilion','Business Atlas','Signal Studio','Blue Edition']
subs=['Die räumliche Wissensbibliothek','Der helle Wissenspavillon','Der erkundbare Betriebsatlas','Das digitale Lernstudio','Die markante digitale Edition']
desc=['Dunkles Navy, saphirblaues Glas und greifbare Produktinszenierung. Ruhige Premiumwirkung mit räumlicher Tiefe.','Helle Architektur, viel Licht und eine klare Verlagssprache. Wissen wirkt zugänglich und hochwertig.','Ein vernetzter Betrieb als interaktive Landkarte. Seitliche Navigation und sichtbare Zusammenhänge.','Filmische Bildbühne, horizontale Sammlungen und ein eigenes Lernstudio für Videos und Reels.','Kräftiges Ultramarin, große Typografie und markante Buchobjekte. Eigenständig und besonders wiedererkennbar.']
css='''*{box-sizing:border-box}body{margin:0;background:#eaf0f7;color:#122b50;font:16px/1.6 "Segoe UI",Arial,sans-serif}main{max-width:1420px;margin:auto;padding:55px 45px}h1{font-size:55px;line-height:1.05;letter-spacing:-.05em;margin:12px 0 25px}h2{font-size:28px;line-height:1.2;margin:12px 0}p{max-width:830px;color:#53647e}a{color:inherit}nav{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}nav a,.button{display:inline-block;border:1px solid #9cb0cf;padding:10px 16px;border-radius:6px;text-decoration:none;background:white}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.card{background:white;border:1px solid #ccdae9;border-radius:12px;overflow:hidden}.card img{width:100%;display:block}.copy{padding:25px}.copy p{margin:12px 0}.kicker{font:12px Consolas,monospace;letter-spacing:.12em}.links{display:flex;flex-wrap:wrap;gap:15px;font-size:13px;margin-top:20px}.board{width:1700px;margin:0;padding:35px;background:#eaf0f7}.board h1{font-size:45px}.board .topview{display:grid;grid-template-columns:1280px 300px;gap:28px}.board .topview img{width:100%;display:block}.board .smallgrid{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:30px}.board figure{margin:0;background:white;border:1px solid #b9c8dc}.board figure img{width:100%;display:block}.board figcaption{padding:10px 18px;font-size:17px;font-weight:600}.overview{width:1800px;margin:0;padding:40px}.overview .grid{grid-template-columns:repeat(3,1fr);gap:22px}.overview h1{font-size:48px}.overview h2{font-size:23px}.overview .copy{padding:18px}@media(max-width:760px){main{padding:30px 18px}h1{font-size:40px}.grid{grid-template-columns:1fr}}'''
Path('gallery.css').write_text(css,encoding='utf-8')
def shell(title,body,cl=''):
 return f'<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="gallery.css"><body class="{cl}">{body}</body></html>'
cards=[]
for n,(name,sub,d) in enumerate(zip(names,subs,desc),1):
 links=''.join(f'<a href="variante-{n}.html?page={p}&lang=de">{l}</a>' for p,l in [('home','Startseite'),('library','Bibliothek'),('product','Produkt'),('tools','Tools'),('media','Studio')])
 cards.append(f'<article class="card"><a href="variante-{n}.html?lang=de"><img src="screenshots/0{n}-home.jpg" alt="Websiteentwurf {name}"></a><div class="copy"><span class="kicker">0{n} / {sub}</span><h2>{name}</h2><p>{d}</p><a class="button" href="variante-{n}.html?lang=de">Website ausprobieren ↗</a><div class="links">{links}<a href="vorlage-0{n}.jpg">Große Bildvorlage</a></div></div></article>')
 top=f'<div class="kicker">SCUTORIA / WEBSITE DESIGN / 0{n}</div><h1>{name} · {sub}</h1><p>{d}</p>'
 hero=f'<div class="topview"><figure><img src="screenshots/0{n}-home.jpg"><figcaption>Startseite · Desktop</figcaption></figure><figure><img src="screenshots/0{n}-mobile.jpg"><figcaption>Mobil</figcaption></figure></div>'
 small=''.join(f'<figure><img src="screenshots/0{n}-{pg}.jpg"><figcaption>{lab}</figcaption></figure>' for pg,lab in [('library','Bibliothek / 20 Titel'),('product','Produktdetail / Muster und Inhalte'),('tools','Tools / Arbeitsbereich'),('media','Studio / YouTube und Reels')])
 Path(f'board-{n}.html').write_text(shell(name,top+hero+'<div class="smallgrid">'+small+'</div><p>Lokaler Designprototyp · neue Titel und Videos sind Konzepte · Animationen in den interaktiven Varianten.</p>','board'),encoding='utf-8')
body='<main><div class="kicker">SCUTORIA / FÜNF PREMIUM-WEBSITES</div><h1>Fünf Wege, Wissen<br>zum Erlebnis zu machen.</h1><p>Fünf eigenständige Websitevarianten mit jeweils Startseite, Bibliothek, Produktdetail, Tools und Videostudio. Öffne einen Entwurf und teste Navigation, Suchfunktion, Themenwechsel und Bewegung. Alle Varianten sind auf Deutsch und Englisch angelegt.</p><nav><a href="CLAUDE-DESIGNBRIEF.md">Designbrief für Claude</a><a href="SCUTORIA-5-DESIGNS.zip">Komplettpaket herunterladen</a><a href="vergleich.jpg">Bildvergleich</a></nav><p>Die Bibliothek demonstriert den Ausbau auf 20 Titel und 10 Tools. Zusätzliche Angebote und Videoformate sind als Konzepte gekennzeichnet. Die Website wurde nicht live verändert.</p><div class="grid">'+''.join(cards)+'</div></main>'
Path('index.html').write_text(shell('Scutoria · Fünf Websitevarianten',body),encoding='utf-8')
mini=''.join(f'<article class="card"><img src="screenshots/0{n}-home.jpg"><div class="copy"><div class="kicker">VARIANTE 0{n}</div><h2>{names[n-1]}</h2><p>{desc[n-1]}</p></div></article>' for n in range(1,6))
Path('overview.html').write_text(shell('Fünf Websitevarianten','<div class="kicker">SCUTORIA / WEBSITE-DESIGN</div><h1>Fünf visuelle Richtungen für Scutoria.</h1><p>Jeweils mit Startseite, Bibliothek, Produktdetail, Tools und Studio · Desktop und Mobil · interaktive Prototypen</p><div class="grid">'+mini+'</div>','overview'),encoding='utf-8')
